import{H as e,V as t,et as n,j as r}from"./chunks/framework.BWKSSupd.js";var i=JSON.parse(`{"title":"Uninstalling","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/meta/uninstall.md","filePath":"en/guide/meta/uninstall.md","lastUpdated":1786185592000}`),a={name:`en/guide/meta/uninstall.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="uninstalling" tabindex="-1">Uninstalling <a class="header-anchor" href="#uninstalling" aria-label="Permalink to “Uninstalling”">​</a></h1><p>Compared to a single-page app, a multi-tab framework provides a better experience for cross-page operations, but it also means more complex interaction scenarios. If your project no longer needs RouterTab, follow these steps to remove it.</p><h2 id="_1-replace-imperative-calls" tabindex="-1">1. Replace Imperative Calls <a class="header-anchor" href="#_1-replace-imperative-calls" aria-label="Permalink to “1. Replace Imperative Calls”">​</a></h2><p>Search for all instance calls obtained via <code>useRouterTab()</code>, and replace them with native Vue Router equivalents per the table below:</p><table tabindex="0"><thead><tr><th>Method</th><th>Description</th><th>Replacement</th></tr></thead><tbody><tr><td><code>tabs.open</code></td><td>Open a brand new tab</td><td><code>router.push(path)</code></td></tr><tr><td><code>tabs.close</code></td><td>Close a tab and navigate away</td><td><code>router.replace(path)</code></td></tr><tr><td><code>tabs.refresh</code> / <code>tabs.refreshAll</code> / <code>tabs.refreshTab</code></td><td>Refresh tabs</td><td>Provide your own data-refresh method inside the component</td></tr><tr><td><code>tabs.reset</code></td><td>Reset to default or a given page</td><td><code>router.replace(path)</code></td></tr><tr><td><code>tabs.reload</code></td><td>Reload the current view</td><td>Provide your own refresh method inside the component</td></tr><tr><td><code>tabs.adjust</code></td><td>Recompute tab bar scroll</td><td>No replacement needed (the tab bar itself is removed)</td></tr><tr><td><code>tabs.openIframe</code> / <code>tabs.closeIframe</code> / <code>tabs.refreshIframe</code></td><td>Iframe tab operations</td><td>Implement your own iframe container and operation methods</td></tr><tr><td><code>useRouterPage({ beforePageLeave })</code></td><td>Leave confirmation</td><td>Vue Router&#39;s <a href="https://router.vuejs.org/guide/advanced/navigation-guards.html#In-Component-Guards" target="_blank" rel="noreferrer">In-Component Guards</a> <code>onBeforeRouteLeave</code></td></tr><tr><td><code>useRouterPage({ routeTab })</code></td><td>Dynamic tab info</td><td>No replacement needed (the tab bar itself is removed)</td></tr><tr><td><code>useRouterPage({ pageScroller })</code> / <code>restoreScroll()</code></td><td>Scroll position memory</td><td>Implement it yourself with <code>onActivated</code> / <code>onDeactivated</code>, or rely on native browser scroll restoration</td></tr></tbody></table><h2 id="_2-remove-the-component" tabindex="-1">2. Remove the Component <a class="header-anchor" href="#_2-remove-the-component" aria-label="Permalink to “2. Remove the Component”">​</a></h2><ol><li><p>Replace <code>&lt;RouterTab&gt;</code> in your layout with <code>&lt;router-view&gt;</code>.</p></li><li><p>Following <a href="./../essentials/#route-configuration">Getting Started</a> in reverse, remove:</p><ul><li><code>app.use(RouterTab)</code> and the style import <code>import &#39;vue-router-tab/dist/index.css&#39;</code> from your entry file</li><li><code>RouterTabRoutes</code> injected into your route config</li><li>The tab config fields under route <code>meta.routerTab</code> (<code>title</code> / <code>key</code> / <code>keepAlive</code> etc. — decide based on your business needs whether to keep fields like <code>title</code> for other purposes)</li></ul></li><li><p>Remove the dependency:</p><div class="language-bash line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remove</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vue-router-tab</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></li></ol><h2 id="_3-adjust-page-interaction-patterns" tabindex="-1">3. Adjust Page Interaction Patterns <a class="header-anchor" href="#_3-adjust-page-interaction-patterns" aria-label="Permalink to “3. Adjust Page Interaction Patterns”">​</a></h2><p>Moving to a single-page approach means cross-page operations are no longer supported. Flows that used to rely on switching tabs need to be reworked as in-page interactions, for example:</p><ul><li>Modal / drawer: temporary forms or detail views</li><li>Route-based tabs (uncached): still need the URL to distinguish state, but don&#39;t need multi-tab management</li><li>Internal page state switching: scenarios that don&#39;t involve route changes, controlled with component-internal <code>ref</code> / <code>reactive</code></li></ul><p>Which approach to use depends on the specific business scenario the original tabs served — there&#39;s no one-size-fits-all solution.</p>`,11)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};